class LmdbLegacyAliasTripleCapacityIsolationTest {
	@Test
	void tripleCapacityFailureIsNotRetriedAsDictionaryCapacity(
			@TempDir(cleanup = CleanupMode.NEVER) Path evidence) throws Exception {
		Path referenceDirectory = evidence.resolve("reference");
		Path targetDirectory = evidence.resolve("target");
		createFixture(referenceDirectory);
		createFixture(targetDirectory);
		LmdbStore reference = new LmdbStore(referenceDirectory.toFile(), config());
		List<String> explicit;
		List<String> all;
		try {
			reference.init();
			explicit = statements(reference, false);
			all = statements(reference, true);
			assertTrue(explicit.size() > 1);
		} finally {
			reference.shutDown();
		}
		FailingStore target = new FailingStore(targetDirectory);
		try {
			SailException failure = assertThrows(SailException.class, target::init);
			Throwable cause = failure;
			while (cause.getCause() != null) {
				cause = cause.getCause();
			}
			assertInstanceOf(LmdbUtil.MapFullException.class, cause,
					"the triple-side failure must remain the reported cause");
			assertEquals(1, target.attempts.get(), "dictionary recovery must not retry a triple-side failure");
			assertTrue(target.mapBefore.get() > 0L, "the real triple rewrite must be reached");
			assertEquals(target.mapBefore.get(), target.values.mapSizeBytes(),
					"a triple-side capacity failure must not grow the value map");
		} finally {
			target.shutDown();
		}
		LmdbStore reopened = new LmdbStore(targetDirectory.toFile(), config());
		try {
			reopened.init();
			assertEquals(explicit, statements(reopened, false));
			assertEquals(all, statements(reopened, true));
		} finally {
			reopened.shutDown();
		}
	}

	private static LmdbStoreConfig config() {
		return new LmdbStoreConfig("spoc,posc,ospc").setTripleTermIndexes("spoc,cspo")
				.setAutoGrow(true).setSketchEstimatorEnabled(false).setPredicateGuaranteeIndexEnabled(false);
	}

	private static void createFixture(Path directory) throws IOException {
		LmdbCompatibilityFixtures.extract("v2-610-language-aliases.zip", directory);
		Properties properties = new Properties();
		properties.setProperty("version", "2");
		properties.setProperty("triple-indexes", "spoc,posc,ospc");
		properties.setProperty("triple-term-indexes", "spoc,cspo");
		try (var output = Files.newOutputStream(directory.resolve("store.properties"))) {
			properties.store(output, null);
		}
	}

	private static List<String> statements(LmdbStore store, boolean includeInferred) {
		List<String> rows = new ArrayList<>();
		try (SailConnection connection = store.getConnection();
				var statements = connection.getStatements(null, null, null, includeInferred)) {
			while (statements.hasNext()) {
				Statement statement = statements.next();
				rows.add(NTriplesUtil.toNTriplesString(statement.getSubject()) + " "
						+ NTriplesUtil.toNTriplesString(statement.getPredicate()) + " "
						+ NTriplesUtil.toNTriplesString(statement.getObject())
						+ (statement.getContext() == null ? "" : " "
								+ NTriplesUtil.toNTriplesString(statement.getContext())));
			}
		}
		Collections.sort(rows);
		return rows;
	}

	private static final class FailingStore extends LmdbStore {
		private final AtomicInteger attempts = new AtomicInteger();
		private final AtomicLong mapBefore = new AtomicLong();
		private volatile ValueStore values;

		private FailingStore(Path directory) {
			super(directory.toFile(), config());
		}

		@Override
		LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean sketches) throws IOException, SailException {
			LmdbSailStore.ValueStoreFactory factory = (path, stored, selected) -> {
				ValueStore created = new ValueStore(path, stored, selected, false, null,
						LmdbStoreFormat.fromProperties(stored, selected), true);
				values = created;
				return created;
			};
			return new LmdbSailStore(directory, properties, config, sketches, factory,
					(path, stored, selected, dictionary) -> new TripleStore(path, stored, selected, dictionary) {
						@Override
						long rewriteStatementIds(LongUnaryOperator resolver, int batchRows,
								StatementRewriteObserver observer) throws IOException {
							if (attempts.incrementAndGet() == 1) {
								mapBefore.set(dictionary.mapSizeBytes());
								LmdbUtil.checkMapFull(LMDB.MDB_MAP_FULL);
							}
							throw new IOException("triple rewrite must not be retried as dictionary growth");
						}
					});
		}
	}
}
